<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { NModal,NCard,NButton,NInput,NSelect,NForm,NFormItem,NAlert,useMessage,useDialog } from 'naive-ui'
import { api,errorText,groupOptions,lines,splitLines,type Group } from '../api'
const props=defineProps<{show:boolean;groups:Group[]}>(),emit=defineEmits<{'update:show':[boolean];changed:[]}>()
const msg=useMessage(),dialog=useDialog(),busy=ref(false),editing=ref(false),proxy=ref(''),form=reactive<Group>({id:'',name:'',parent_id:'',proxies:[]})
const options=computed(()=>groupOptions(props.groups).filter(g=>g.value!==form.id))
function edit(g?:Group){Object.assign(form,g||{id:'',name:'',parent_id:'',proxies:[]});proxy.value=splitLines(g?.proxies);editing.value=true}
async function save(){busy.value=true;try{await api('admin/groups','POST',{...form,parent_id:form.parent_id||'',proxies:lines(proxy.value)});msg.success('分组已保存');editing.value=false;emit('changed')}catch(e){msg.error(errorText(e))}finally{busy.value=false}}
function remove(g:Group){dialog.warning({title:'删除分组',content:`删除“${g.name}”？请先移出下级分组及邮箱。`,positiveText:'删除',negativeText:'取消',onPositiveClick:async()=>{try{await api('admin/groups/'+g.id,'DELETE');emit('changed')}catch(e){msg.error(errorText(e))}}})}
</script>
<template><NModal :show="show" @update:show="v=>emit('update:show',v)"><NCard class="form-modal" title="分组与代理" closable @close="emit('update:show',false)"><NAlert :show-icon="false" type="info">最多三级分组。账号优先使用自己的代理，其次沿上级分组继承；均为空时直连。代理按顺序尝试，最多 3 个。</NAlert><template v-if="editing"><NForm @submit.prevent="save"><NFormItem label="分组名称"><NInput v-model:value="form.name" placeholder="例如：业务邮箱" maxlength="80" /></NFormItem><NFormItem label="上级分组"><NSelect v-model:value="form.parent_id" clearable :options="options" placeholder="顶级分组" /></NFormItem><NFormItem label="代理（每行一个，留空继承）"><NInput v-model:value="proxy" type="textarea" :rows="3" placeholder="socks5://user:pass@host:1080 或 https://host:8080" /></NFormItem><div class="form-actions"><NButton @click="editing=false">返回列表</NButton><NButton type="primary" attr-type="submit" :loading="busy">保存分组</NButton></div></NForm></template><template v-else><div class="list-editor"><div v-for="g in groupOptions(groups)" :key="g.value" class="editor-row"><strong>{{ g.label }}</strong><div class="row"><NButton quaternary @click="edit(groups.find(x=>x.id===g.value))">编辑</NButton><NButton quaternary type="error" @click="remove(groups.find(x=>x.id===g.value)!)">删除</NButton></div></div><p v-if="!groups.length" class="empty">还没有分组</p></div><div class="form-actions"><NButton type="primary" @click="edit()">新建分组</NButton></div></template></NCard></NModal></template>
